"""Controlled notification transitions; history generated by unrelated stress is not truth."""

import time
from harness import Ref, pathref


def build(s):
    a = s.api
    for actor, peer in [("alice", "bob"), ("bob", "carol"), ("carol", "bob")]:
        name = "pbp-notify-" + actor
        rp = "repos/" + actor + "/" + name
        key = "notification-" + actor
        a(
            "notification-fixture",
            actor,
            "repository",
            "POST",
            "user/repos",
            actor,
            body={"name": name, "auto_init": True},
            status=201,
        )
        a(
            "notification-fixture",
            actor,
            "issue",
            "POST",
            rp + "/issues",
            peer,
            body={
                "title": "Notification target " + actor,
                "body": "Controlled notification episode",
            },
            status=201,
            save=key + "-issue",
        )
        a(
            "notification-fixture",
            actor,
            "comment",
            "POST",
            pathref(rp + "/issues/{n}/comments", n=Ref(key + "-issue", "number")),
            peer,
            body={"body": "Notify " + actor},
            status=201,
            save=key + "-comment",
        )

        def settled(c, actor=actor, key=key, rp=rp):
            comment = c.state[key + "-comment"]["id"]
            deadline = time.monotonic() + 12
            while True:
                r, items = c.request(
                    "GET", rp + "/notifications", actor, params={"all": True}
                )
                matches = (
                    [
                        x
                        for x in items
                        if isinstance(x, dict)
                        and x.get("subject", {})
                        .get("latest_comment_url", "")
                        .endswith("/" + str(comment))
                    ]
                    if isinstance(items, list)
                    else []
                )
                if r.status_code == 200 and len(matches) == 1:
                    break
                assert (
                    time.monotonic() < deadline
                ), "notification queue did not expose the completed comment"
                time.sleep(0.1)
            c.state[key] = matches[0]
            return c.observe(r, matches)

        s.add("notification-fixture", actor, "await-delivery", settled)
        ep = pathref("notifications/threads/{id}", id=Ref(key, "id"))
        a(
            "notifications",
            actor,
            "thread",
            "GET",
            ep,
            actor,
            status=200,
            want={"unread": True},
        )
        for mode, params in [
            ("unread", {}),
            ("all", {"all": True}),
            ("read", {"status-types": ["read"]}),
            ("issues", {"subject-type": ["issue"]}),
            ("pulls", {"subject-type": ["pull"]}),
            ("first-page", {"all": True, "limit": 1, "page": 1}),
            ("beyond-page", {"all": True, "limit": 1, "page": 2}),
        ]:
            a(
                "notifications",
                actor + "-" + mode,
                "repo-list",
                "GET",
                rp + "/notifications",
                actor,
                params=params,
                status=200,
            )
        outsider = "carol" if actor != "carol" else "bob"
        a("notifications", actor, "other-user-denied", "GET", ep, outsider, status=403)

        def global_membership(c, actor=actor, key=key):
            r, items = c.request(
                "GET", "notifications", actor, params={"all": True, "limit": 50}
            )
            assert r.status_code == 200
            matches = [x for x in items if x["id"] == c.state[key]["id"]]
            assert len(matches) == 1
            return c.observe(r, matches)

        s.add("notifications", actor, "global-membership", global_membership)

        def count_consistency(c, actor=actor):
            r, p = c.request("GET", "notifications/new", actor)
            assert r.status_code == 200 and type(p["new"]) is int and p["new"] >= 1
            rr, items = c.request(
                "GET",
                "notifications",
                actor,
                params={"status-types": ["unread"], "limit": 50},
            )
            assert rr.status_code == 200
            assert p["new"] == len(items), "unread count does not equal unread threads"
            return {
                "status": 200,
                "unread_count_matches_collection": True,
                "contains_pending_notification": True,
            }

        s.add("notifications", actor, "unread-count-consistency", count_consistency)
        a(
            "notifications",
            actor,
            "mark-read",
            "PATCH",
            ep,
            actor,
            params={"to-status": "read"},
            status=205,
            want={"unread": False},
        )
        a(
            "notifications",
            actor,
            "unread-empty",
            "GET",
            rp + "/notifications",
            actor,
            status=200,
            check=lambda c, r, p: (
                (_ for _ in ()).throw(
                    AssertionError("read notification remained unread")
                )
                if p
                else None
            ),
        )
        a(
            "notifications",
            actor,
            "read-list",
            "GET",
            rp + "/notifications",
            actor,
            params={"status-types": ["read"]},
            status=200,
        )
        a(
            "notifications",
            actor,
            "pin",
            "PATCH",
            ep,
            actor,
            params={"to-status": "pinned"},
            status=205,
            want={"pinned": True},
        )
        a(
            "notifications",
            actor,
            "pinned-list",
            "GET",
            rp + "/notifications",
            actor,
            params={"status-types": ["pinned"]},
            status=200,
        )
        a(
            "notifications",
            actor,
            "unread-again",
            "PATCH",
            ep,
            actor,
            params={"to-status": "unread"},
            status=205,
            want={"unread": True, "pinned": False},
        )
        a(
            "notifications",
            actor,
            "mark-repository-read",
            "PUT",
            rp + "/notifications",
            actor,
            params={"all": True, "to-status": "read"},
            status=205,
        )
        a(
            "notifications",
            actor,
            "repository-read",
            "GET",
            rp + "/notifications",
            actor,
            status=200,
            check=lambda c, r, p: (
                (_ for _ in ()).throw(
                    AssertionError("repository notification remained unread")
                )
                if p
                else None
            ),
        )
